INSERT INTO settings (key, value) VALUES ('meta', '{"generated":"2026-11-14","data_as_of":"2025-06-30","version":"1.1","line_count":14416,"agreements":[{"name":"MFN (WTO)","type":"Base","partners":"All countries without an applicable FTA/PTA","inforce":"-","notif":"Customs Tariff Act, 1975 - First Schedule","commitment":"Standard/statutory BCD","modelled":"Yes - column D of FTA_Rate_Matrix","col":"MFN","exclusions":"AIDC, anti-dumping and safeguard duties apply in addition where notified","roo":"-","status":"Applies","source":"CBIC working tariff / Notif. 45/2025-Customs as amended"},{"name":"India-ASEAN FTA (AIFTA)","type":"FTA","partners":"Brunei, Cambodia, Indonesia, Lao PDR, Malaysia, Myanmar, Philippines, Singapore, Thailand, Vietnam","inforce":"01-Jan-2010","notif":"46/2011-Customs (14-Jun-2011)","commitment":"0% on the Normal Track by 2016; Sensitive Track cut to 5%; ~489 lines in India''s Exclusion List","modelled":"Yes - derived by chapter/line rule","col":"AIFTA","exclusions":"Agri (Ch 1-24), petroleum (Ch 27) and motor vehicles (8701-8706) treated as excluded; Sensitive-Track lines may attract 5% instead of 0%.","roo":"RVC 35% + CTSH (general); product-specific rules for chemicals, textiles, steel, etc.","status":"In force","source":"CBIC Notif. 46/2011-Customs; AIFTA schedule"},{"name":"India-UAE CEPA","type":"CEPA","partners":"United Arab Emirates","inforce":"01-May-2022","notif":"22/2022-Customs (30-Apr-2022)","commitment":"0% on ~80% of lines immediately, ~90% within 10 years; TRQs for dates, copper, etc.","modelled":"Yes - line-level rates for the agri subset from public dataset; remainder derived by chapter rule","col":"UAE_CEPA","exclusions":"Agri lines use the published CEPA rate where available; other Ch 1-24 lines and motor vehicles treated as excluded.","roo":"RVC 40% or CTSH (product-specific rules in Annex 3B)","status":"In force","source":"CBIC Notif. 22/2022-Customs; indiaftaduty.com dataset (subset)"},{"name":"India-Japan CEPA","type":"CEPA","partners":"Japan","inforce":"01-Aug-2011","notif":"69/2011-Customs","commitment":"~90% of industrial lines at 0% by 2021; agri excluded","modelled":"Yes - derived by chapter rule","col":"Japan_CEPA","exclusions":"Agri (Ch 1-24) and motor vehicles treated as excluded; some industrial lines remain in the negative list.","roo":"RVC 35% + CTSH (general)","status":"In force","source":"CBIC Notif. 69/2011-Customs"},{"name":"India-Korea CEPA","type":"CEPA","partners":"Republic of Korea","inforce":"01-Jan-2010","notif":"Verify (CEPA implementing notification, 2009/2010)","commitment":"0% on ~85% of lines by 2021; agri excluded","modelled":"Yes - derived by chapter rule","col":"Korea_CEPA","exclusions":"Agri (Ch 1-24) and motor vehicles treated as excluded; sensitive industrial lines may carry 5%.","roo":"RVC 35% + CTSH (general)","status":"In force","source":"CBIC CEPA notification (verify number)"},{"name":"India-Australia ECTA","type":"ECTA","partners":"Australia","inforce":"29-Dec-2022","notif":"62/2022-Customs","commitment":"India: duty-free on 40.3% of lines immediately, a further ~30% phased to zero; TRQs/exclusions for dairy, cereals, sugar, apples, walnuts, chickpeas","modelled":"Yes - derived by chapter rule","col":"Australia_ECTA","exclusions":"Ch 1-24 treated as excluded (several are TRQ/staged rather than fully excluded).","roo":"WO / RVC 40% / CTSH + RVC (product-specific)","status":"In force","source":"CBIC Notif. 62/2022-Customs"},{"name":"India-Mauritius CECPA","type":"CECPA","partners":"Mauritius","inforce":"01-Apr-2021","notif":"25/2021-Customs","commitment":"Line-specific concessions on ~615 tariff lines (textiles, footwear, processed food, some engineering goods)","modelled":"No - line-specific list not modelled (MFN shown)","col":"Mauritius_CECPA","exclusions":"Only listed lines get a concession. Cells show MFN as a conservative placeholder - verify against the CECPA schedule.","roo":"RVC 35% + CTSH; direct consignment","status":"In force","source":"CBIC Notif. 25/2021-Customs"},{"name":"India-Sri Lanka ISFTA","type":"FTA","partners":"Sri Lanka","inforce":"2000","notif":"26/2000-Customs","commitment":"0% on all lines except India''s Negative List (~429 lines)","modelled":"Yes - derived by chapter rule","col":"SriLanka_ISFTA","exclusions":"Agri treated as excluded; the actual Negative List is line-specific.","roo":"WO / 35% domestic value addition; direct consignment","status":"In force","source":"CBIC Notif. 26/2000-Customs"},{"name":"SAFTA","type":"FTA","partners":"Afghanistan, Bangladesh, Bhutan, Maldives, Nepal, Pakistan, Sri Lanka","inforce":"01-Jan-2006","notif":"75/2006-Customs (verify)","commitment":"0% for LDC/Non-LDC members by 2013 except country-specific Sensitive Lists (~614 lines for India)","modelled":"Yes - derived by chapter rule","col":"SAFTA","exclusions":"Sensitive Lists differ by partner and are line-specific; chapter-level approximation only.","roo":"RVC 40% + CTSH; SAPTA/SAFTA certificate of origin","status":"In force","source":"CBIC SAFTA notification (verify number)"},{"name":"India-Singapore CECA","type":"CECA","partners":"Singapore","inforce":"01-Aug-2005","notif":"79/2005-Customs","commitment":"0% on almost all lines; a small negative list","modelled":"Yes - derived by chapter rule","col":"Singapore_CECA","exclusions":"Agri treated as excluded; some lines remain dutiable.","roo":"RVC 40% / CTSH; direct consignment","status":"In force","source":"CBIC Notif. 79/2005-Customs"},{"name":"India-Malaysia MICECA","type":"CECA","partners":"Malaysia","inforce":"01-Jul-2011","notif":"Verify","commitment":"0% on most lines; agri and autos excluded","modelled":"Yes - derived by chapter rule","col":"Malaysia_MICECA","exclusions":"Agri and motor vehicles treated as excluded.","roo":"RVC 35% + CTSH","status":"In force","source":"CBIC MICECA notification (verify number)"},{"name":"India-Nepal Treaty of Trade","type":"Treaty","partners":"Nepal","inforce":"Treaty of Trade (rev. 2009)","notif":"Treaty -